// Auto-capture Bearer token on successful login
if (pm.response.code === 200) {
    var rawText = pm.response.text().trim();
    // Magento returns token either as quoted string "abc..." or raw string
    var cleanToken = rawText.replace(/^"|"$/g, '').trim();
    if (cleanToken && cleanToken.length > 10 && !cleanToken.includes("message")) {
        pm.collectionVariables.set("token", cleanToken);
        console.log("✅ Bearer token automatically saved to {{token}}:", cleanToken);
    }
}

