// Auto-capture Order ID
if (pm.response.code === 200) {
    try {
        var json = pm.response.json();
        var orderId = json.order_id || json.entity_id || json.increment_id || pm.response.text().replace(/^"|"$/g, '');
        pm.collectionVariables.set("orderId", String(orderId));
        console.log("✅ Order ID automatically saved to {{orderId}}:", orderId);
    } catch(e) {
        var raw = pm.response.text().trim().replace(/^"|"$/g, '');
        pm.collectionVariables.set("orderId", raw);
    }
}
